# hypothesis: assigning __len__ on an instance (self.__len__ = fn) does not make len() work, because CPython looks special methods up on the type, so len(s) raises TypeError while a checker that trusts the instance attribute accepts it.
from collections.abc import Callable


def fixed_len() -> int:
    return 3


class Shadow:
    def __init__(self, fn: Callable[[], int]) -> None:
        self.__len__ = fn


class Control:
    def __len__(self) -> int:
        return 5


def probe_shadow(s: Shadow) -> str:
    try:
        n = len(s)  # expect-error: __len__ is looked up on the type, not the instance
    except TypeError:
        return 'TypeError'
    return str(n)


print(probe_shadow(Shadow(fixed_len)))
print(len(Control()))
